<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');
$id_questionario=intval($_GET['id']??$_POST['id']??0); if($id_questionario<=0){header('Location: questionarios_secretaria.php');exit();}
$mensagem='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['excluir'])){
    $stmt=$conexao->prepare('SELECT COUNT(*) AS total FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta WHERE p.id_questionario=?');$stmt->bind_param('i',$id_questionario);$stmt->execute();$tem_respostas=(int)$stmt->get_result()->fetch_assoc()['total']>0;$stmt->close();
    if($tem_respostas){$mensagem='<div style="background:#fff4e5;color:#8a5a00;padding:10px;border-radius:8px;margin-bottom:15px;">O questionário não pode ser excluído porque já possui respostas enviadas.</div>';}else{$conexao->begin_transaction();$stmt=$conexao->prepare('SELECT id_pergunta FROM pergunta WHERE id_questionario=?');$stmt->bind_param('i',$id_questionario);$stmt->execute();$result=$stmt->get_result();$ids=[];while($row=$result->fetch_assoc()){$ids[]=(int)$row['id_pergunta'];}$stmt->close();$ok=true;if($ids){$stmt=$conexao->prepare('DELETE FROM alternativa WHERE id_pergunta=?');foreach($ids as $id_pergunta){$stmt->bind_param('i',$id_pergunta);$ok=$stmt->execute()&&$ok;}$stmt->close();}$stmt=$conexao->prepare('DELETE FROM pergunta WHERE id_questionario=?');$stmt->bind_param('i',$id_questionario);$ok=$stmt->execute()&&$ok;$stmt->close();$stmt=$conexao->prepare('DELETE FROM questionario WHERE id_questionario=?');$stmt->bind_param('i',$id_questionario);$ok=$stmt->execute()&&$ok;$stmt->close();if($ok){$conexao->commit();header('Location: questionarios_secretaria.php');exit();}$conexao->rollback();$mensagem='<div style="background:#fee;color:#9d1c1c;padding:10px;border-radius:8px;margin-bottom:15px;">Não foi possível excluir o questionário.</div>';}}
$stmt=$conexao->prepare('SELECT q.*,u.nome AS criador FROM questionario q JOIN usuario u ON u.id_usuario=q.criado_por WHERE q.id_questionario=?');$stmt->bind_param('i',$id_questionario);$stmt->execute();$questionario=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$questionario){header('Location: questionarios_secretaria.php');exit();}
$perguntas=[];$stmt=$conexao->prepare('SELECT id_pergunta,enunciado FROM pergunta WHERE id_questionario=? ORDER BY id_pergunta');$stmt->bind_param('i',$id_questionario);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$perguntas[$row['id_pergunta']=$row['id_pergunta']]=$row;}$stmt->close();
$alternativas=[];if($perguntas){$ids=array_keys($perguntas);$placeholders=implode(',',array_fill(0,count($ids),'?'));$tipos_ids=str_repeat('i',count($ids));$stmt=$conexao->prepare("SELECT id_pergunta,texto FROM alternativa WHERE id_pergunta IN ($placeholders) ORDER BY id_alternativa");$stmt->bind_param($tipos_ids,...$ids);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$alternativas[$row['id_pergunta']][]=$row['texto'];}$stmt->close();}
$respostas=[];$stmt=$conexao->prepare('SELECT u.id_usuario,u.nome,m.id_turma,t.nome AS turma_nome,p.enunciado,r.resposta FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta JOIN usuario u ON u.id_usuario=r.id_usuario LEFT JOIN matricula m ON m.id_aluno=u.id_usuario LEFT JOIN turma t ON t.id_turma=m.id_turma WHERE p.id_questionario=? ORDER BY u.nome,p.id_pergunta');$stmt->bind_param('i',$id_questionario);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$respostas[$row['id_usuario']]['nome']=$row['nome'];$respostas[$row['id_usuario']]['turma']=$row['turma_nome']??'Sala não informada';$respostas[$row['id_usuario']]['itens'][]=$row;}$stmt->close();
?>
<!DOCTYPE html>
<html lang="pt-br"><head><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Questionário</title><style>
