not(#atlas-mobile-toggle),.danger,.voltar{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;background:#6664df;color:#fff;padding:12px 17px;font:inherit;font-size:12px;font-weight:700;text-decoration:none;cursor:pointer;min-height:42px}.btn:hover,.novo:hover,button:not(#atlas-toggle):not(#atlas-mobile-toggle):hover{background:#5552c9}.secundario,.voltar,button.secundario{background:#efeeff!important;color:#5653c4!important}.danger,button.danger{background:#b94353!important;color:#fff!important}.botoes,.acoes{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px;align-items:center}.pergunta{border:1px solid #e7e9f1;border-radius:13px;padding:20px;margin:15px 0;background:#fcfcff}.pergunta strong{color:#292c43}.pergunta ul{color:#777d93}.resposta{margin:10px 0}.aluno{border:1px solid #e7e9f1;border-radius:12px;padding:19px;margin:14px 0}.aluno h3{margin:0 0 12px;font-size:15px}.aluno p{border-top:1px solid #f0f0f5;padding-top:10px;font-size:13px}.conteudo{white-space:normal;line-height:1.8;color:#42465c}.cabecalho p{color:#777d93}.resultados{border:1px solid #e7e9f1;border-radius:10px;margin-top:6px;max-height:210px;overflow:auto}.resultado,button.resultado{display:block;width:100%;text-align:left;background:#fff!important;color:#252741!important;border-radius:0;padding:10px 12px}.resultado:hover{background:#f1f0ff!important}.badge{display:inline-block;border-radius:100px;padding:5px 10px;font-size:11px;font-weight:700}.badge.nova{background:#fff0f1;color:#aa3443}.badge.lida{background:#e9f7ef;color:#26744a}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #edf0f5}th{color:#777d93;font-size:11px;text-transform:uppercase;letter-spacing:.06em}td a,.assunto{color:#5552c9;text-decoration:none}.nao-lida{font-weight:700}.panel:has(table){overflow-x:auto}@media(max-width:800px){main{padding:78px 20px 50px}}@media(max-width:580px){.panel,.box{padding:20px}.filtros form{min-width:100%;flex-wrap:wrap}.filtros input{min-width:100%}.acoes{align-items:stretch}.acoes>*{flex:1}}
</style></head><body><?php include '../../includes/menu_secretaria.php'; ?><main><section class="header"><h1><?php echo htmlspecialchars($questionario['titulo']); ?></h1><p><?php echo htmlspecialchars($questionario['descricao']??''); ?></p></section><?php echo $mensagem; ?><section class="panel"><h2>Perguntas</h2><?php foreach($perguntas as $pergunta): ?><div class="pergunta"><strong><?php echo htmlspecialchars($pergunta['enunciado']); ?></strong><?php if(!empty($alternativas[$pergunta['id_pergunta']])):?><ul><?php foreach($alternativas[$pergunta['id_pergunta']] as $alternativa): ?><li><?php echo htmlspecialchars($alternativa); ?></li><?php endforeach; ?></ul><?php endif; ?></div><?php endforeach; ?><?php if(!$perguntas): ?><p>Nenhuma pergunta preenchida.</p><?php endif; ?></section><section class="panel"><h2>Respostas enviadas</h2><?php if($respostas):foreach($respostas as $aluno): ?><div class="aluno"><h3><?php echo htmlspecialchars($aluno['nome'].' - '.$aluno['turma']); ?></h3><?php foreach($aluno['itens'] as $item): ?><p><strong><?php echo htmlspecialchars($item['enunciado']); ?></strong><br><?php echo nl2br(htmlspecialchars($item['resposta'])); ?></p><?php endforeach; ?></div><?php endforeach;else:?><p>Nenhuma resposta enviada.</p><?php endif; ?></section><section class="acoes"><a class="voltar" href="questionarios_secretaria.php">Voltar</a><form method="POST" onsubmit="return confirm('Confirma a exclusão deste questionário?');"><input type="hidden" name="id" value="<?php echo $id_questionario; ?>"><button class="danger" name="excluir" value="1">Excluir questionário</button></form></section></main></body></html>
